(function () {
  var nav = document.getElementById('nav'), menu = document.getElementById('mobileMenu'), burger = document.getElementById('burger');
  function onScroll() { nav.classList.toggle('is-stuck', window.scrollY > 12); }
  window.addEventListener('scroll', onScroll, { passive: true }); onScroll();
  if (burger && menu) {
    burger.addEventListener('click', function () { menu.classList.toggle('is-open'); });
    menu.querySelectorAll('a').forEach(function (a) { a.addEventListener('click', function () { menu.classList.remove('is-open'); }); });
  }
})();
